insert into calendar_posts (date,time,brand,platform,type,phase,title,graphic,caption) values ('2026-07-20','07:00','body_recode','instagram','authority','scale',E'BR · Mon · THE READ · State of the Data',E'/calendar/br-w1_mon_state-of-data_01.png,/calendar/br-w1_mon_state-of-data_02.png,/calendar/br-w1_mon_state-of-data_03.png,/calendar/br-w1_mon_state-of-data_04.png,/calendar/br-w1_mon_state-of-data_05.png,/calendar/br-w1_mon_state-of-data_06.png,/calendar/br-w1_mon_state-of-data_07.png,/calendar/br-w1_mon_state-of-data_08.png',E'Every client we''ve had shares one thing. Not their age, not their job, not how hard they train - their body state. Every one of them read Depleted.\nAnd these are high-functioning people. Execs, professionals, busy parents. The last people you''d call ''depleted.''\nThat''s the catch. Discipline hides it. You can feel fine and still be running on empty.\nSo where are you actually at? Find your state - link in bio, takes two minutes.');
insert into calendar_posts (date,time,brand,platform,type,phase,title,graphic,caption) values ('2026-07-21','12:30','body_recode','instagram','contrarian','scale',E'BR · Tue · THE MISREAD · menopause',E'/calendar/br-w1_tue_misread.png',E'If you''re over 40 and everything''s suddenly harder, you''ve probably been told it''s just menopause. Eat less, move more.\nHere''s what that misses. An estrogen shift changes how your body stores fat and responds to training. The old plan didn''t stop working because you got lazy - your body changed states.\nAnd ''just eat less''? That tells an already-stressed body it''s still under threat, so it holds on harder.\nIt''s not menopause. It''s a misread. Find out what your body''s actually doing - link in bio.');
insert into calendar_posts (date,time,brand,platform,type,phase,title,graphic,caption) values ('2026-07-22','07:00','body_recode','instagram','pattern','scale',E'BR · Wed · THE PATTERN · 3pm crash',E'/calendar/br-w1_wed_3pm-crash_01.png,/calendar/br-w1_wed_3pm-crash_02.png,/calendar/br-w1_wed_3pm-crash_03.png,/calendar/br-w1_wed_3pm-crash_04.png,/calendar/br-w1_wed_3pm-crash_05.png,/calendar/br-w1_wed_3pm-crash_06.png',E'Let''s talk about your 3pm crash.\nIt''s not a coffee problem. It''s a cortisol rhythm problem. Cortisol is meant to peak in the morning and taper off, but under chronic stress it flattens and fires at the wrong times. So you''re wired at night and flat by mid-afternoon.\nWhich is exactly why you can''t out-discipline it. The crash is a signal your body''s in protection mode.\nWant to know which state you''re in? Two minutes, free - link in bio.');
insert into calendar_posts (date,time,brand,platform,type,phase,title,graphic,caption) values ('2026-07-24','18:00','body_recode','instagram','coach','scale',E'BR · Fri · THE STORY · just getting old',E'/calendar/br-w1_fri_story.png',E'A guy came to me last year. 52, a partner at his firm. Convinced what he was feeling was just getting old.\nNo drive. Recovery shot. Sharp one day, foggy the next. His GP ran the bloods and said they were ''fine.''\nBut ''fine'' bloods aren''t the same as a body that''s working. Underneath, he was running years of stress and travel in a depleted state, and nobody had actually read it. They''d just told him to push harder or accept it.\nWe read the state first. Within weeks, the things ''just getting older'' never explained started shifting.\nIf you''ve quietly accepted ''this is just my age'' - get the read first. Link in bio.');
insert into calendar_posts (date,time,brand,platform,type,phase,title,graphic,caption) values ('2026-07-26','09:00','body_recode','instagram','ad','scale',E'BR · Sun · PROMO · join the Challenge',E'/calendar/br-w1v2_sun_challenge-promo.png',E'You don''t need another meal plan. You need a read.\nThat''s the whole idea behind the free 14-Day Body Decode Challenge. For 14 days, we read what your body''s actually doing - the thing that should come before anyone hands you a plan.\nNo calorie-slashing. No punishing sessions. No credit card. And you keep the result.\nBy day 14 you''ll know your state, why the effort hasn''t been landing, and what your body will actually respond to.\nCome do it with us. Join the free 14-day Challenge - link in bio.');
